+/** Chooses a supported language from an Accept-Language header, or `fallback`. */
+export function pickLanguage(header, fallback = "en") {
+  if (typeof header !== "string" || !header.trim()) return fallback;
+  const choices = [];
+  for (const part of header.split(",")) {
+    const [rawTag, ...params] = part.trim().split(";");
+    const tag = rawTag.trim().toLowerCase();
+    if (!tag || !/^[a-z0-9]+(?:[-_][a-z0-9]+)*$/.test(tag)) continue;
+    const lang = tag.split(/[-_]/)[0];
+    if (!LANGUAGES.includes(lang)) continue;
+    let q = 1;
+    let valid = true;
+    for (const p of params) {
+      const m = /^q\s*=\s*(.+)$/i.exec(p.trim());
+      if (!m) continue;
+      const n = Number(m[1]);
+      if (!Number.isFinite(n) || n < 0 || n > 1) {
+        valid = false;
+        break;
+      }
+      q = n;
+    }
+    if (valid && q > 0) choices.push({ lang, q });
+  }
+  if (!choices.length) return fallback;
+  choices.sort((a, b) => b.q - a.q);
+  return choices[0].lang;
+}
